style.css:
@-moz-document domain("example.com") {
/* ── Global Pink Text ── */
  :root {
    --pink-light: #ffb3c6;
    --pink-mid:   #ff6b9d;
    --pink-deep:  #c9184a;
    --pink-glow:  #ff4d94;
  }

  *, *::before, *::after {
    color: var(--pink-mid);
  }

  h1, h2, h3, h4, h5, h6 {
    color: var(--pink-deep);
    text-shadow: 0 0 18px var(--pink-glow), 0 0 40px rgba(255, 77, 148, 0.3);
  }

  a { color: var(--pink-light); text-decoration-color: var(--pink-glow); }
  a:hover { color: var(--pink-glow); }

  small, .muted, figcaption {
    color: color-mix(in srgb, var(--pink-mid) 60%, white);
  }
}
